import uploadConfig from "@/views/client/mixins/uploadConfig";
export default {
  name: "UploadSetting",
  mixins: [uploadConfig],
  props: {
    show: {
      type: Boolean,
      default: false,
      required: true
    }
  },
  data() {
    return {
      showSetting: true
    };
  },
  watch: {
    show(val) {
      this.showSetting = val;
    },
    showSetting(val) {
      this.$emit("update:show", val);
    }
  },
  computed: {
    dialogWidth() {
      return window.innerWidth > 768 ? "680px" : "90%";
    }
  },
  mounted() {
    this.showSetting = this.show;
    // 获取默认配置
    this.uploadFolder = this.$store.getters["client/storeUploadFolder"] || this.$store.getters["user/storeUserConfig"]?.defaultUploadFolder || "";
  }
};