// 上传配置相关
export default {
  computed: {
    // 复制链接格式
    urlForm: {
      get() {
        return this.$store.getters["client/storeUploadCopyUrlForm"] || "url";
      },
      set(value) {
        this.$store.commit("client/setUploadCopyUrlForm", value);
      },
    },
    // 默认文件前缀
    urlPrefix() {
      return (
        this.$store.getters["base/storeUserConfig"].urlPrefix ||
        `${window.location.protocol}//${window.location.host}/file/`
      );
    },
    // 自定义链接设置
    useCustomUrl: {
      get() {
        return this.$store.getters["client/storeCustomUrlSettings"].useCustomUrl || false;
      },
      set(value) {
        this.$store.commit("client/setCustomUrlSettings", { key: "useCustomUrl", value });
      },
    },
    // 自定义链接前缀
    customUrlPrefix: {
      get() {
        return this.$store.getters["client/storeCustomUrlSettings"].customUrlPrefix || "";
      },
      set(value) {
        this.$store.commit("client/setCustomUrlSettings", { key: "customUrlPrefix", value });
      },
    },
    // 上传渠道
    uploadChannel: {
      get() {
        return (
          this.$store.getters["client/storeUploadChannel"] ||
          this.$store.getters["user/storeUserConfig"]?.defaultUploadChannel ||
          "telegram"
        );
      },
      set(value) {
        this.$store.commit("client/setUploadChannel", value);
      },
    },
    // 上传失败自动重试
    uploadRetry: {
      get() {
        return this.$store.getters["client/storeAutoRetry"] || false;
      },
      set(value) {
        this.$store.commit("client/setAutoRetry", value);
      },
    },
    // 文件命名格式
    uploadNameType: {
      get() {
        return (
          this.$store.getters["client/storeUploadNameType"] ||
          this.$store.getters["user/storeUserConfig"]?.defaultUploadNameType ||
          "default"
        );
      },
      set(value) {
        this.$store.commit("client/setUploadNameType", value);
      },
    },
    // 是否启用客户端压缩
    useClientCompress: {
      get() {
        return this.$store.getters["client/storeCompressConfig"].customerCompress || false;
      },
      set(value) {
        this.$store.commit("client/setCompressConfig", { key: "customerCompress", value });
      },
    },
    // 客户端压缩阈值
    clientCompressBar: {
      get() {
        return this.$store.getters["client/storeCompressConfig"].compressBar || 10;
      },
      set(value) {
        this.$store.commit("client/setCompressConfig", { key: "compressBar", value });
      },
    },
    // 客户端压缩期望大小
    clientCompressQuality: {
      get() {
        return this.$store.getters["client/storeCompressConfig"].compressQuality || 5;
      },
      set(value) {
        this.$store.commit("client/setCompressConfig", { key: "compressQuality", value });
      },
    },
    // 是否启用服务端压缩
    useServerCompress: {
      get() {
        return this.$store.getters["client/storeCompressConfig"].serverCompress || false;
      },
      set(value) {
        this.$store.commit("client/setCompressConfig", { key: "serverCompress", value });
      },
    },
    // 上传方式
    uploadMethod: {
      get() {
        return this.$store.getters["client/storeUploadMethod"] || "default";
      },
      set(value) {
        this.$store.commit("client/setUploadMethod", value);
      },
    },
    // 上传目录
    uploadFolder: {
      get() {
        return this.$store.getters["client/storeUploadFolder"] || "";
      },
      set(value) {
        if (this.validateUploadFolder(value)) {
          this.$store.commit("client/setUploadFolder", value);
        }
      },
    },
  },

  methods: {
    validateUploadFolder(path) {
      // 如果路径为空，返回true（允许空路径）
      if (!path || path.trim() === "") {
        return true;
      }
      // 检查路径是否以/开头
      if (!path.startsWith("/")) {
        this.$message.error('上传目录必须以 "/" 开头');
        return false;
      }
      // 检查路径是否包含非法字符
      const invalidChars = /[\\:\*\?"'<>\| \(\)\[\]\{\}#%\^`~;@&=\+\$,]/;
      if (invalidChars.test(path)) {
        this.$message.error("上传目录包含非法字符，请使用合法的路径格式");
        return false;
      }
      // 检查路径是否包含连续的斜杠
      if (path.includes("//")) {
        this.$message.error("上传目录不能包含连续的斜杠");
        return false;
      }
      return true;
    },
  },

  mounted() {
    // 读取用户设置的上传文件夹和上传方式
    this.uploadFolder =
      this.$store.getters["client/storeUploadFolder"] ||
      this.$store.getters["user/storeUserConfig"]?.defaultUploadFolder ||
      "";
    this.uploadMethod =
      this.$store.getters["client/storeUploadMethod"] ||
      this.$store.getters["user/storeUserConfig"]?.defaultUploadFolder ||
      "";
  },
};
